--[[
	Midnight Helper — Italian strings (itIT).
	Load order: after Core.lua + enUS.lua, before Locale.lua and the topical
	Locale packs (those merge into ns._mhLocales.itIT).

	Partial pack: any key not present here falls back to English via ns:L().
	Convention: WoW proper nouns (spell/ability/boss/NPC/zone/dungeon/raid
	names, currencies & items like "Coffer Key", "Renown", class names,
	"Mythic+", "Delve", "Omnium Folio") stay in English; surrounding UI text
	and prose are translated to natural Italian. Preserve %s/%d/%1$s format
	specifiers, |cff......|r colour codes and \n escapes exactly.
]]

local _, ns = ...

ns._mhLocales = ns._mhLocales or {}

-- Locale-gating (Spec 11 3a): only build this pack when the client is itIT.
-- enUS + nlNL always load, so auto-detect and forced Dutch keep working; forcing
-- itIT on another client shows a login notice and loads once the client is itIT.
if GetLocale() ~= "itIT" then
	return
end

