	DELVELOG_LBL_KEY = "Key",
	DELVELOG_TOTAL_TIME = "Tempo totale:",
	INFO_DRAWER_BODY_DELVELOG = "Il Delve Log registra ogni delve di Midnight che completi su questo personaggio. Clicca una delve per espandere le run recenti. Ogni run mostra tier, tempo di clear, morti, se hai speso una Restored Coffer Key e il boss finale. Traccia le run in background; non serve tenere aperta questa tab.",
	TAB_WORLD = "Void & Rituals",
	TAB_EVENTS = "Events",
	EVENTS_SUBTITLE = "Tutti gli eventi mondo di Midnight: cosa succede ora e cosa arriva nel prossimo giorno. Clicca un evento attivo per impostare un percorso; passa il mouse per sapere cos'è e cosa dà.",
	EVENTS_NONE = "Nessun evento mondo visibile in questo momento — lo scheduler potrebbe essere ancora in caricamento. Riprova tra qualche secondo.",
	WORLD_SUBTITLE = "Il contenuto mondo settimanale di Midnight in Quel'Thalas. Una Ritual Site è attiva in una zona e il Void ne assalta un'altra — entrambi condividono l'hub del Bazaar, i Field Accolades e il renown.",
	INFO_DRAWER_BODY_WORLD = "Void & Rituals combina i due sistemi mondo a rotazione di Midnight. Ritual Sites: disturba il sito attivo (icona viola sulla mappa) al suo Curious Obelisk. Void Assaults: elimina i Void Strikes nella zona attiva per innescare una Void Incursion. Entrambi danno Field Accolades, riempiono la riga World del tuo Great Vault e alimentano il renown condiviso delle Ritual Sites. Prendi entrambe le settimanali all'hub del Bazaar a Silvermoon City.",
	TAB_REFERENCE = "Basics",
	REF_PANEL_INTRO = "Spiegazioni semplici per i sistemi endgame. Altri argomenti appariranno qui col tempo.",
	REF_MORE_COMING = "Altre guide alle professioni in arrivo (blacksmithing, jewelcrafting, mining, cooking, fishing e altro).",
	INFO_DRAWER_BODY_REFERENCE = "Guide adatte ai principianti: Dawncrests, dove spenderli e i bonus Warband. Altri argomenti (professioni, ecc.) verranno aggiunti qui.",
