	ACADEMY_SUBTITLE = "Breve masterclass per tanking e healing in gruppo - mentalità, checklist di preparazione e un avvicinamento graduale ai dungeon. Non è una guida ai parse.",
	ACADEMY_TRACK_TANK = "Percorso Tank",
	ACADEMY_TRACK_HEAL = "Percorso Heal",
	ACADEMY_LINK_MACROS = "Macros",
	ACADEMY_LINK_CONSUMABLES = "Consumables",
	ACADEMY_LINK_GUIDE = "Guide",
	ACADEMY_LINK_DELVES = "Delves",
	ACADEMY_LINK_CLASS = "La mia classe",
	ACADEMY_CLASS_FMT = "Connesso: %s - %s (apri Macros / Consumables / Guide dalla sidebar)",
	ACADEMY_CLASS_OPEN_CHAT_FMT = "Aperti i Macros per %s - %s. Controlla anche Consumables per flask e pozioni.",

	ACADEMY_PREF_TITLE = "Checklist pre-volo (spunta quando sei pronto)",
	ACADEMY_PREF_HINT = "Le spunte sono salvate nelle tue impostazioni. Apri la tab corrispondente dalla sidebar quando ti prepari.",
	ACADEMY_PREF_TANK_INTERRUPT = "Macro di interrupt sulla barra (tab Macros)",
	ACADEMY_PREF_TANK_DEFENSIVE = "Una difensiva pronta (Guide -> Defensives o tab In groups)",
	ACADEMY_PREF_TANK_CONSUMABLES = "Flask / pozione pronta (tab Consumables)",
	ACADEMY_PREF_TANK_TAUNT = "Conosco il mio tasto di taunt (provalo una volta sul dummy)",
	ACADEMY_PREF_HEAL_MACROS = "Macro di cura mouseover / focus (tab Macros)",
	ACADEMY_PREF_HEAL_DEFENSIVE = "Difensiva personale sulla barra (Guide -> Defensives o In groups)",
	ACADEMY_PREF_HEAL_CONSUMABLES = "Pozione di mana / flask (tab Consumables)",
	ACADEMY_PREF_HEAL_PRACTICE = "Provato l'hover-heal su un amico una volta",

	ACADEMY_TANK_INTRO_TITLE = "Mentalità Tank",
	ACADEMY_TANK_INTRO_BODY = "Il tuo compito è dettare il ritmo e tenere l'attenzione - non stare in cima ai meter dei danni.\n\nUn pull costante batte una rotazione perfetta su un gruppo morto. Annuncia i pull ad alta voce se aiuta: \"pull tra 3\".",
	ACADEMY_TANK_PULL_TITLE = "Durante un pull (primi 10 secondi)",
	ACADEMY_TANK_PULL_BODY = "1. Prendi il pacchetto (taunt / threat).\n2. Gira i nemici lontano dal gruppo quando puoi.\n3. Usa una difensiva se i danni picchiano - tieni la seconda per l'\"oh no\".\n4. Interrompi il cast che fa più male (spesso una cura o un colpo grosso).\n\nNon ti serve ogni abilità in cooldown subito.",
	ACADEMY_TANK_WIPE_TITLE = "Quando va male",
	ACADEMY_TANK_WIPE_BODY = "Un wipe è un dato, non un verdetto. Chiediti: \"Ero troppo avanti?\" o \"Ho tenuto una difensiva?\"\n\nRipara, mangia, riprova.",
	ACADEMY_TANK_DUNGEON_TITLE = "Il tuo primo dungeon (normal)",
	ACADEMY_TANK_DUNGEON_BODY = "Inizia in normal con amici o gildani se puoi. Vai piano sui pull - due pacchetti piccoli battono una catena enorme.\n\nTieni d'occhio il mana del guaritore; fai pause tra i pull. Va bene chiedere CC o \"niente pull grosso per ora\".",
	ACADEMY_TANK_RAID_TITLE = "Raid e LFR (più avanti)",
	ACADEMY_TANK_RAID_BODY = "L'LFR è l'intro gentile al raid: indulgente, tanti guaritori. Concentrati sui tempi di taunt del boss e sullo stare fermo nel posto giusto.\n\nIl tanking in Mythic raid non è il passo successivo - prima comfort in heroic/LFR.",
	ACADEMY_TANK_CHAT_TITLE = "Chat di gruppo",
	ACADEMY_CHAT_HINT = "Clicca una riga o l'icona di copia, poi Ctrl+C per incollarla nella chat di gruppo.",
	ACADEMY_CHAT_COPY_TIP = "Seleziona questa riga (Ctrl+C)",
	ACADEMY_TANK_CHAT_BODY = "\"Sto ancora imparando a tankare - andate piano per favore.\"\n\"Pull tra 3...\"\n\"Mi serve un attimo per il mana.\"\n\"Interrupt su [nome spell] - ce l'ho il prossimo.\"\n\"Ancora un tentativo - ora conosco quel pull.\"",
	ACADEMY_TANK_LADDER_TITLE = "Scala dell'ansia (ordine consigliato)",
	ACADEMY_TANK_LADDER_BODY = "1. Elite del mondo aperto con un amico\n2. Delve (istanza più piccola - tab Delves)\n3. Dungeon normal con persone di cui ti fidi\n4. Heroic / LFR quando sei a tuo agio\n\nSalta un passo solo quando ti annoia, non quando ti terrorizza.",
	ACADEMY_TANK_BOTH_TITLE = "Stai imparando anche a curare?",
	ACADEMY_TANK_BOTH_BODY = "Ottimo - ma scegli un ruolo principale nei dungeon per un po'. Allena l'altro nelle delve o nel mondo aperto.\n\nAlternare tank e heal nello stesso pug M+ raddoppia lo stress; padroneggiare prima un ruolo crea fiducia per il secondo.",

	ACADEMY_HEAL_INTRO_TITLE = "Mentalità Heal",
	ACADEMY_HEAL_INTRO_BODY = "Non sei responsabile di tenere tutti al 100% di vita per tutto il tempo.\n\nIl tuo compito è il triage: tieni vivo il tank, salva chi sta per morire, poi il resto. Un po' di danno è normale - l'overheal nel panico svuota il mana.",
	ACADEMY_HEAL_TRIAGE_TITLE = "Triage (chi per primo?)",
	ACADEMY_HEAL_TRIAGE_BODY = "1. Tu (se stai morendo - un guaritore morto non cura nessuno)\n2. Tank (se il pacchetto è ancora su di lui)\n3. Chiunque sotto ~40% o con un debuff letale\n4. Tutti gli altri con cure efficienti\n\nCura grossa dopo danno grosso; cure piccole tra un evento e l'altro.",
	ACADEMY_HEAL_WIPE_TITLE = "Quando va male",
	ACADEMY_HEAL_WIPE_BODY = "\"Potevo salvare il tank?\" è la domanda utile - non \"perché i DPS stavano nel fuoco?\"\n\nSe il mana era vuoto, usa spell più efficienti la prossima volta. Un wipe non significa che non sai curare.",
	ACADEMY_HEAL_DUNGEON_TITLE = "Il tuo primo dungeon (normal)",
	ACADEMY_HEAL_DUNGEON_BODY = "Di' al gruppo che stai imparando. Stai a portata del tank; lascia che i DPS prendano un graffio prima di sparare mana.\n\nTra i pull: bevi, buffa, respira. Puoi dire \"oom, 5 sec\".",
	ACADEMY_HEAL_RAID_TITLE = "Raid e LFR (più avanti)",
	ACADEMY_HEAL_RAID_BODY = "LFR: il danno a tutto il raid è prevedibile dopo un wipe. Impara il timer della fight, non le barre di ogni giocatore.\n\nLe cure da raid usano lo stesso triage - prima le finestre di cooldown di tank e raid.",
	ACADEMY_HEAL_CHAT_TITLE = "Chat di gruppo",
	ACADEMY_HEAL_CHAT_BODY = "\"Guaritore alle prime armi - segnalerò quando ho poco mana.\"\n\"Il tank è la priorità - urla se ti serve un attimo.\"\n\"Cura grossa su di te - occhio alla vita.\"\n\"Oom 5 sec tra i pull.\"\n\"Quella era colpa mia - terrò più cure per il tank al prossimo pull.\"",
	ACADEMY_HEAL_LADDER_TITLE = "Scala dell'ansia (ordine consigliato)",
	ACADEMY_HEAL_LADDER_BODY = "1. Cura un amico nel mondo aperto\n2. Delve con un piccolo gruppo\n3. Dungeon normal con amici pazienti\n4. Raid LFR / heroic quando sei pronto\n\nLe delve sono il passo più dolce verso il contenuto istanziato.",
	ACADEMY_HEAL_BOTH_TITLE = "Stai imparando anche a tankare?",
	ACADEMY_HEAL_BOTH_BODY = "Usa il percorso Tank per le code dei dungeon; continua a curare nelle delve finché tankare non ti diventa familiare.\n\nDue ruoli in una settimana nei pug è tanto - un ruolo come \"main\" riduce la paura.",

	INFO_DRAWER_BODY_ACADEMY = "Role Academy: percorsi tank/heal, checklist pre-volo, note dungeon vs raid e righe per la chat di gruppo. Le Leveling Guides aggiungono una tab In groups advisor per ruolo. Usa la sidebar per Macros, Consumables, Guide e Delves.",
