	LAYOUT_KEY_TAB_TOOLTIP = "Tab cambia bersaglio. WoW lo usa di default — tieni Tab libero per scegliere in fretta il nemico giusto in combattimento.",
	LAYOUT_KEY_PREFERRED_TOOLTIP = "Consiglio Midnight: tieni questo tasto libero per spell, macro o combo Shift/Ctrl/Alt — stessa idea dei tasti F illuminati sulle tue action bar.",
	LAYOUT_LEGEND = "|cff33ff61Verde|r = movimento (W A S D).\n|cffe0e070Oro|r = spell e scorciatoie su questa mappa.\n|cff59d9ffTab|r = cambia bersaglio in fretta.\n|cff888888Grigio|r = non su questa mappa iniziale.",
	LAYOUT_KEY_HIGHLIGHT_FROM_GUIDE = "|cffe0e070Aperto dalla tua guida di leveling — questo tasto è sulla mappa Midnight.|r",
	GUIDE_TIP_LAYOUT_KEY_BTN_FMT = "Mostra il tasto |cffe0e070%s|r sul layout della tastiera",
	GUIDE_TIPS_KEY_HINT = "Il team Midnight usa tasti fissi per le spell (sempre lo stesso posto). I pulsanti oro a destra aprono la tab Layout e mostrano dove sta quella spell sulla tua tastiera — costruisci memoria muscolare invece di cercare nelle barre a ogni fight.",
	GUIDE_CONS_COPY_TITLE = "Copia per l'Auction House",
	GUIDE_CONS_COPY_HINT = "Clicca la casella, poi Ctrl+C. Incolla nella ricerca dell'Auction House.",

	MODULE_PLACEHOLDER = "Segnaposto del modulo — il contenuto per \"%s\" verrà montato qui.",
	INFO_DRAWER_TOGGLE_SHOW = "Info",
	INFO_DRAWER_TOGGLE_HIDE = "Chiudi",
	INFO_DRAWER_TITLE_FMT = "%s - Come si usa",
	INFO_DRAWER_BODY_DELVES = "Centro di comando per le Midnight Delves del tuo personaggio attuale.\n\nEspandi Great Vault per il tracciamento delle ricompense settimanali, o Midnight Delves per le valute stagionali (Restored Coffer Keys, Shards settimanali, Undercoins), Delver's Journey / renown, e l'elenco completo delle delve con rilevamento bountiful in tempo reale dai POI della mappa.\n\nNavigazione: clic destro su una riga per tracciare un percorso all'ingresso. |cffffcc00TomTom (consigliato)|r aggiunge la freccia sulla mappa e la coda di waypoint. |cff00ff00Travel Assistant|r (popup quando sei lontano) mostra le scorciatoie per Hearthstone e portali hub e funziona |cffffff00senza|r TomTom.\n\nFind Nearest Bountiful richiede TomTom installato.",
	INFO_DRAWER_BODY_ACCOUNT = "Roster tra personaggi salvato localmente da questo addon (saved variable sul tuo PC—non la sincronizzazione cloud Blizzard).\n\nOgni riga elenca Keys, Shards, Undercoins, echo delle professioni e un riepilogo compatto del Great Vault con tooltip ricche; il personaggio con cui sei connesso è evidenziato e l'ordinamento favorisce l'utilità.\n\nLe righe si aggiornano al login e agli eventi di valuta / settimanali. L'eliminazione rimuove solo i dati snapshot dell'addon—mai il tuo vero personaggio WoW.",
	INFO_DRAWER_BODY_RARES = "Rare del mondo di Midnight per zona (Eversong, Zul'Aman, Harandar, Voidstorm).\n\nScegli una zona nella colonna di sinistra. Le righe dei rare mostrano verde = fatto su questo personaggio, freccia verde SU = vignette sulla mappa vicino allo spawn (probabilmente spawnato ora), trattino grigio = non ancora nei dati della tua mappa.\n\nFind Nearest Rare traccia un percorso a un pin; Generate Route mette in coda tutti i rare incompleti in TomTom (il più vicino prima, come le Professioni). La vignette SU è best-effort — apri la mappa della zona o avvicinati se sembra sbagliato.",
	RARES_TITLE = "Rare di Midnight",
	RARES_SUBTITLE_FMT = "%d/%d fatti su questo personaggio · %d visibili sulla mappa ora (stella d'argento)",
	RARES_EMPTY_ZONE = "Nessuna lista di rare per questa zona.",
	RARES_ALL_DONE_WEEK = "Tutti i rare fatti questa settimana su questo personaggio — reset mercoledì.",
	RARES_BTN_NEAREST = "Find Nearest Rare",
	RARES_BTN_ROUTE = "Generate Route",
	RARES_NEAREST_ROUTE = "|cffffff78Midnight Helper:|r TomTom: rare più vicino — %s",
	RARES_NEAREST_NONE = "Nessun rare incompleto rimasto in questa zona.",
	RARES_NEAREST_NO_TRAVEL = "Travel Assistant non disponibile (modulo Delves non caricato).",
	RARES_ROUTE_DONE_FMT = "Messi in coda %d/%d rare incompleti in TomTom. %s",
	RARES_ROUTE_ORDER_NEAR = "Ordine: il più vicino prima, poi il successivo più vicino a ogni passo.",
	RARES_ROUTE_ORDER_LIST = "Ordine: ordine della lista (posizione non disponibile).",
	RARES_TAG_UP = "SU",
	RARES_TAG_DOWN = "—",
	RARES_TIP_DONE = "Fatto questa settimana su questo personaggio (reset mercoledì).",
	RARES_TIP_UP = "Probabilmente attivo ora (vignette sulla mappa vicino al punto di spawn).",
	RARES_TIP_DOWN = "Non visto sulla mappa al momento — potrebbe ancora spawnare più tardi.",
	RARES_TIP_VIGNETTE_NOTE = "Lo stato della vignette è best-effort; apri la mappa della zona o avvicinati se non sei sicuro.",
	INFO_DRAWER_BODY_SMC = "Riferimento di Silvermoon City per Midnight (mappa 2393). Lo stesso scroll inizia con la checklist Settimanale / hub quando gli ID delle quest sono configurati, poi continua in griglie di pin categorizzate—Servizi essenziali, Viaggio, Hub di quest, Addestratori di professione, Raccolta e altro.\n\nOgni pulsante di posizione imposta il waypoint utente di Blizzard e, con TomTom installato, lo rispecchia tramite l'helper slash (/way #2393 …).\n\nIl progresso della checklist colora di verde i pulsanti waypoint correlati; aggiorna gli ID delle quest nei dati dopo le patch importanti se una riga sembra sbagliata.",
	INFO_DRAWER_BODY_PROFESSIONS = "Traccia i Knowledge Points (KP) di professione di Midnight per il tuo personaggio attuale, più le righe di valuta quando il client le espone (Unalloyed Abundance, Artisan's Moxie, Shards of Dundun settimanali).\n\nSotto, due colonne elencano le quest di Knowledge Pickup e i libri di professione per mestiere—le icone mostrano se ogni quest è completa. Clicca una riga per inviare solo quel pin a TomTom (azzera gli altri waypoint; il Travel Assistant gestisce i salti tra zone quando TomTom è caricato).\n\nI pulsanti in basso mettono in coda i pin incompleti in blocco: Generate Treasures o Generate Books (il più vicino non finito prima quando la tua posizione sulla mappa è disponibile).",
	INFO_DRAWER_BODY_GUIDE = "Riferimenti di leveling spec per spec in stile Icy Veins: priorità delle stat, scelte di gear, consumabili filtrati su ciò che il tuo livello può davvero usare, righe opzionali di suggerimenti sulle spell, e il Leveling Advisor con tab a fasce per rotazione, difensive e focus dei talenti.\n\nQuando la tua classe ha una mappa dei tasti Midnight (per ora Hunter / Paladin), i suggerimenti possono mostrare un pulsante-tasto oro — cliccalo per aprire la tab Layout ed evidenziare quel tasto sulla tastiera. Questo collega la lettura (cosa premere) al posizionamento (dove sulla tastiera), così impari facendo.\n\nLa barra di ricerca globale capisce le parole-chiave delle guide e può saltare tra le tab di Midnight Helper; Anteprima ti fa leggere un'altra specializzazione senza rilogarti mentre Il mio personaggio torna alla tua spec attiva.\n\nLa visibilità della tab Guide segue le Impostazioni: Auto (si nasconde al livello 90+), Mostra sempre o Nascondi sempre.",
	INFO_DRAWER_BODY_MACROS = "Tab Interrupt: macro di kick del team (prima il focus). Tab Utility: macro extra per spec (spell a terra col cursore, cure mouseover e simili) dal pacchetto del team. Scegli una riga, leggi il suggerimento, copia il testo.\n\nI dati possono cambiare dopo le patch - segnala le spell mancanti al team.",
	INFO_DRAWER_BODY_ADDONS = "Hub per strumenti opzionali inclusi dentro Midnight Helper invece che come download separati.\n\nScegli una sotto-tab in alto—oggi è Platynator: link Wago, import di profile-string e la galleria visiva MF Platynator.\n\nAltri pannelli partner si registrano qui automaticamente quando arriveranno moduli futuri.",
	ABOUT_WINDOW_TITLE = "Info su Midnight Helper",
	ABOUT_VERSION_FMT = "Versione installata: |cffffcc00%s|r",
	ABOUT_WINDOW_BODY = "Autori: Inchy & Gemma & Cursor\n\nIl tuo compagno Midnight tutto-in-uno, organizzato in quattro stanze — Me, Codex, Tools e Settings. Fissa i preferiti sotto la barra di ricerca e digita per saltare ovunque. Con Questa settimana, Delves & Vault, coach di Delve e Ritual, il consigliere Incantesimi e Gemme, riepilogo account, guide del Codex, professioni e strumenti integrati — EN / NL / DE / FR / ES / PT / IT.",
	MAIN_TITLE_VERSION_FMT = "v%s",
